import random
import json
from typing import List, Tuple

# Safe, seeded generator for interesting JSON inputs for YAJL fuzzing.
# Fixes: ensure recursion always decreases and bottoms out; cap container sizes.

MAX_SIZE = 4096

ESCAPE_CHARS = [
    "\\\"",  # escaped quote
    "\\\\",   # backslash
    "\\/",    # slash (htmlSafe path)
    "\\b",
    "\\f",
    "\\n",
    "\\r",
    "\\t",
]

UNICODE_POINTS = [
    0x0000, 0x0008, 0x0009, 0x000A, 0x000D, 0x001F,
    0x0020, 0x0022, 0x005C,
    0x00A9, 0x00E9,
    0x0401, 0x0416,
    0x20AC,
    0xD7FF, 0xE000,
    0xFFFD,
    0x1F600, 0x1F642,
]

LIPSUM_WORDS = (
    "lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua".split()
)


def rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))


def rand_int(r: random.Random, lo: int, hi: int) -> int:
    return r.randint(lo, hi)


def rand_choice(r: random.Random, seq):
    return seq[r.randrange(len(seq))]


def gen_number_literal(r: random.Random) -> str:
    kind = r.randrange(6)
    if kind == 0:
        return str(rand_int(r, -1000, 1000))
    if kind == 1:
        sign = "-" if rand_bool(r) else ""
        digits = str(r.randrange(1, 10)) + "".join(str(r.randrange(10)) for _ in range(r.randrange(5, 15)))
        return sign + digits
    if kind == 2:
        return "0" if rand_bool(r) else "-0"
    if kind == 3:
        whole = str(rand_int(r, -1_000_000, 1_000_000))
        frac_len = r.randrange(1, 8)
        frac = "".join(str(r.randrange(10)) for _ in range(frac_len))
        return f"{whole}.{frac}"
    if kind == 4:
        base = str(rand_int(r, -1_000_000, 1_000_000))
        exp_sign = "+" if rand_bool(r) else "-"
        exp = rand_int(r, 0, 50)
        return f"{base}e{exp_sign}{exp}"
    frac_len = r.randrange(1, 10)
    frac = "".join(str(r.randrange(10)) for _ in range(frac_len))
    return f"0.{frac}"


def encode_json_string_component(r: random.Random, max_len: int) -> str:
    parts: List[str] = []
    # guard against zero/negative
    target_len = max(0, max_len)
    while len("".join(parts)) < target_len:
        t = r.randrange(6)
        if t == 0:
            parts.append(rand_choice(r, LIPSUM_WORDS))
        elif t == 1:
            parts.append(rand_choice(r, ESCAPE_CHARS))
        elif t == 2:
            if rand_bool(r):
                cp = rand_choice(r, UNICODE_POINTS)
                if 0x10000 <= cp <= 0x10FFFF:
                    cp0 = cp - 0x10000
                    hi = 0xD800 + (cp0 >> 10)
                    lo = 0xDC00 + (cp0 & 0x3FF)
                    parts.append("\\u%04X\\u%04X" % (hi, lo))
                else:
                    parts.append("\\u%04X" % cp)
            else:
                parts.append("\\u%04X" % rand_int(r, 0, 0xFFFF))
        elif t == 3:
            ln = r.randrange(1, 5)
            for _ in range(ln):
                ch = r.randrange(0x20, 0x7F)
                if ch in (0x22, 0x5C):
                    continue
                parts.append(chr(ch))
        elif t == 4:
            cp = rand_choice(r, UNICODE_POINTS)
            try:
                parts.append(chr(cp))
            except ValueError:
                parts.append("\uFFFD")
        else:
            parts.append(" ")
        if len("".join(parts)) >= target_len:
            break
    return "".join(parts)[:target_len]


def gen_string(r: random.Random, max_len: int = 64) -> str:
    target = r.randrange(0, max(1, max_len) + 1)
    inner = encode_json_string_component(r, target)
    return json.dumps(inner)


def gen_scalar(r: random.Random) -> str:
    # Non-recursive scalar
    choice = r.randrange(6)
    if choice == 0:
        return gen_string(r)
    if choice == 1:
        return gen_number_literal(r)
    if choice == 2:
        return "true" if rand_bool(r) else "false"
    if choice == 3:
        return "null"
    if choice == 4:
        return json.dumps(str(gen_number_literal(r)))
    return gen_string(r, max_len=256)


def gen_value(r: random.Random, depth: int) -> str:
    # Ensure depth never increases and bottoms out
    if depth <= 0:
        return gen_scalar(r)
    choice = r.randrange(6)
    if choice <= 3:
        return gen_scalar(r)
    if choice == 4:
        return gen_array(r, depth - 1)
    return gen_object(r, depth - 1)


def gen_array(r: random.Random, depth: int) -> str:
    # Keep small to avoid deep recursion fan-out
    n = rand_int(r, 0, 5)
    elems = [gen_value(r, depth) for _ in range(n)] if depth >= 0 else [gen_scalar(r) for _ in range(n)]
    return "[" + ",".join(elems) + "]"


def gen_object(r: random.Random, depth: int) -> str:
    n = rand_int(r, 0, 5)
    items = []
    for _ in range(n):
        key = gen_string(r, max_len=32) if rand_bool(r) else json.dumps(rand_choice(r, LIPSUM_WORDS))
        val = gen_value(r, depth) if depth >= 0 else gen_scalar(r)
        items.append(f"{key}:{val}")
    return "{" + ",".join(items) + "}"


def maybe_wrap_comments(r: random.Random, text: str) -> str:
    if not rand_bool(r):
        return text
    inserts: List[Tuple[int, str]] = []
    for i, ch in enumerate(text):
        if ch in ",[}]":
            if r.random() < 0.15 and len(inserts) < 16:
                c = rand_choice(r, ["/*c*/", "//x\n"])
                inserts.append((i + 1, c))
    if not inserts:
        return text
    s = list(text)
    for pos, ins in sorted(inserts, key=lambda x: -x[0]):
        s[pos:pos] = list(ins)
    return "".join(s)


def gen_complete_document(r: random.Random) -> str:
    depth = rand_int(r, 1, 3)
    root = gen_value(r, depth)
    doc = root
    if r.random() < 0.25:
        parts = [root]
        for _ in range(r.randrange(1, 3)):
            parts.append(gen_value(r, depth))
        ws = [" ", "\n", "\t", "\r\n"]
        doc = (rand_choice(r, ws)).join(parts)
    doc = maybe_wrap_comments(r, doc)
    return doc


def gen_partial_fragment(r: random.Random) -> str:
    constructors = []
    if rand_bool(r):
        elems = [gen_value(r, 1) for _ in range(rand_int(r, 0, 3))]
        s = "[" + ",".join(elems)
        if rand_bool(r) and elems:
            s += ","
        constructors.append(s)
    if rand_bool(r):
        pairs = []
        for _ in range(rand_int(r, 0, 3)):
            pairs.append(f"{gen_string(r, 16)}:{gen_value(r, 1)}")
        s = "{" + ",".join(pairs)
        if rand_bool(r) and pairs:
            s += ","
        constructors.append(s)
    if rand_bool(r):
        inner = encode_json_string_component(r, rand_int(r, 1, 40))
        constructors.append('"' + inner)
    if not constructors:
        return "["
    return rand_choice(r, constructors)


def ensure_size_limit(s: str) -> str:
    b = s.encode('utf-8')
    if len(b) <= MAX_SIZE:
        return s
    cut = MAX_SIZE
    while cut > 0 and (b[cut - 1] & 0xC0) == 0x80:
        cut -= 1
    return b[:cut].decode('utf-8', errors='ignore')


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    scenario = r.random()
    if scenario < 0.70:
        s = gen_complete_document(r)
    elif scenario < 0.85:
        s = gen_partial_fragment(r)
    else:
        parts = [gen_value(r, rand_int(r, 1, 2)) for _ in range(rand_int(r, 2, 4))]
        sep = rand_choice(r, ["\n", " ", "\n\n", "\t"]) 
        s = sep.join(parts)
        s = maybe_wrap_comments(r, s)
    s = ensure_size_limit(s)
    return s.encode('utf-8')
